CREATE TABLE IF NOT EXISTS workflow_versions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),definition_id TEXT NOT NULL REFERENCES workflow_definitions(id),version INTEGER NOT NULL,graph TEXT NOT NULL,created_by TEXT REFERENCES users(id),created_at INTEGER NOT NULL,UNIQUE(definition_id,version));
CREATE TABLE IF NOT EXISTS workflow_runs(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),definition_id TEXT REFERENCES workflow_definitions(id),version INTEGER NOT NULL,graph TEXT NOT NULL,input TEXT NOT NULL,status TEXT NOT NULL,current_node TEXT,error TEXT,requested_by TEXT REFERENCES users(id),idempotency_key TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(organization_id,idempotency_key));
CREATE TABLE IF NOT EXISTS workflow_run_steps(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),run_id TEXT NOT NULL REFERENCES workflow_runs(id),node_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,input TEXT,output TEXT,error TEXT,attempts INTEGER NOT NULL DEFAULT 0,duration_ms INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(run_id,node_id));
CREATE TABLE IF NOT EXISTS lead_project_links(lead_id TEXT NOT NULL REFERENCES leads(id),organization_id TEXT NOT NULL REFERENCES organizations(id),project_id TEXT NOT NULL REFERENCES projects(id),quote_id TEXT REFERENCES quotes(id),created_at INTEGER NOT NULL,PRIMARY KEY(organization_id,lead_id));
CREATE INDEX IF NOT EXISTS idx_workflow_runs_org ON workflow_runs(organization_id,created_at);
CREATE INDEX IF NOT EXISTS idx_workflow_steps_org ON workflow_run_steps(organization_id,run_id);
